PREVIEW_HTML = """<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>万相 · 可视化预览</title>
<style>
:root{color-scheme:dark;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif;background:#0b0f16;color:#e8edf5}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% 0,#26204455,transparent 40%),#0b0f16}header{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;border-bottom:1px solid #252d3b;background:#101620}header strong{letter-spacing:3px}header span{color:#7f8a9e;font-size:12px}.brand{display:flex;align-items:center;gap:10px}.brand i{width:28px;height:28px;display:grid;place-items:center;border-radius:8px;background:#7968df;font-style:normal;font-weight:700}main{display:grid;grid-template-columns:340px 1fr;gap:18px;padding:22px;min-height:calc(100vh - 64px)}section{border:1px solid #283243;border-radius:13px;background:#111823;overflow:hidden}.input{padding:22px}.input h1{margin:0 0 8px;font-size:21px}.input p{margin:0 0 20px;color:#8491a5;font-size:12px;line-height:1.7}label{display:block;margin:14px 0 7px;color:#a4afbf;font-size:11px}textarea,select{width:100%;border:1px solid #354157;border-radius:8px;outline:none;background:#0d141e;color:#e5ebf4;padding:11px;font:inherit;font-size:12px}textarea{height:180px;resize:vertical;line-height:1.7}textarea:focus,select:focus{border-color:#8876e7}button{border:0;border-radius:8px;padding:11px 16px;background:#7968df;color:white;font:inherit;font-size:12px;font-weight:600;cursor:pointer}button:disabled{opacity:.5;cursor:wait}.generate{width:100%;margin-top:18px}.output{display:flex;flex-direction:column;min-width:0}.output-header{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #283243}.output-header h2{margin:0;font-size:15px}.output-header span{color:#8d7be0;font-size:10px}.explanation{padding:10px 18px;color:#8996a9;font-size:11px;border-bottom:1px solid #283243}.stage{flex:1;min-height:560px;background:#0e131c}.stage iframe{display:block;width:100%;height:100%;min-height:560px;border:0}.empty{display:grid;place-items:center;height:100%;min-height:560px;color:#6f7d91;font-size:13px;text-align:center;line-height:2}.graph{padding:24px;display:flex;flex-wrap:wrap;gap:14px;align-items:center;justify-content:center}.node{max-width:240px;padding:14px;border:1px solid #514778;border-radius:10px;background:#1b2030}.node strong{display:block;font-size:13px}.node p{margin:6px 0 0;color:#8996aa;font-size:10px}.arrow{color:#8978df}.formula{padding:35px}.formula code{display:block;padding:28px;border:1px solid #334055;border-radius:10px;background:#0c121b;color:#c8baff;font-size:25px;text-align:center}.variable{display:flex;gap:20px;padding:12px;border-bottom:1px solid #293345;color:#94a1b4;font-size:12px}.variable b{color:#c5b5ff}.error{padding:20px;color:#ff9fb0;white-space:pre-wrap}@media(max-width:850px){main{grid-template-columns:1fr}.input textarea{height:120px}.stage,.stage iframe,.empty{min-height:440px}}
</style></head><body>
<header><div class="brand"><i>万</i><strong>万相</strong></div><span>ARTIFACT PREVIEW</span></header>
<main><section class="input"><h1>让概念变得可见</h1><p>输入一个问题，万相会自主选择合适的可视化工具和表达形式。</p>
<label for="source">文本或问题</label><textarea id="source">张量形状为(2,3)，分别说明 axis=0、1、2 插入维度是什么意思</textarea>
<label for="preference">表达偏好</label><select id="preference"><option value="auto">智能选择</option><option value="interactive">交互解释</option><option value="process">流程关系</option><option value="concept">概念关系</option><option value="formula">公式</option></select>
<label for="style">视觉风格</label><select id="style"><option value="anime">动漫风</option><option value="newspaper">报刊风</option><option value="watercolor">水彩风</option><option value="pixel">像素风</option><option value="textbook">教材风</option><option value="blueprint">蓝图风</option><option value="minimal">极简风</option><option value="chalk">黑板风</option></select>
<button class="generate" id="generate">生成可视化</button><p id="status"></p></section>
<section class="output"><div class="output-header"><h2 id="title">可视化画布</h2><span id="engine"></span></div><div class="explanation" id="explanation">结果会显示在这里</div><div class="stage" id="stage"><div class="empty">输入内容并点击“生成可视化”<br>开放 HTML 产物中的按钮和滑块也可以直接操作</div></div></section>
</main><script>
const button=document.getElementById('generate'),stage=document.getElementById('stage'),status=document.getElementById('status');
function graphView(graph){const nodes=new Map(graph.nodes.map(n=>[n.id,n]));const root=document.createElement('div');root.className='graph';for(const node of graph.nodes){const card=document.createElement('div');card.className='node';card.innerHTML='<strong></strong><p></p>';card.querySelector('strong').textContent=node.label;card.querySelector('p').textContent=node.description;root.appendChild(card);if(graph.edges.some(e=>e.source===node.id)){const arrow=document.createElement('span');arrow.className='arrow';arrow.textContent='→';root.appendChild(arrow)}}return root}
function formulaView(formula){const root=document.createElement('div');root.className='formula';const code=document.createElement('code');code.textContent=formula.latex;root.appendChild(code);for(const item of formula.variables){const row=document.createElement('div');row.className='variable';const symbol=document.createElement('b');symbol.textContent=item.symbol;const meaning=document.createElement('span');meaning.textContent=item.meaning;row.append(symbol,meaning);root.appendChild(row)}return root}
button.onclick=async()=>{const startedAt=performance.now(),text=document.getElementById('source').value.trim();if(!text)return;button.disabled=true;button.textContent='正在理解与生成…';status.textContent='复杂开放产物可能需要数十秒';try{const response=await fetch('/v2/visualizations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,preference:document.getElementById('preference').value,style:document.getElementById('style').value})});const data=await response.json();if(!response.ok)throw new Error(data.detail||'生成失败');document.getElementById('title').textContent=data.title;document.getElementById('engine').textContent=data.engine;document.getElementById('explanation').textContent=data.explanation;stage.replaceChildren();if(data.artifact_type==='html'){const frame=document.createElement('iframe');frame.sandbox='allow-scripts';frame.srcdoc=data.html.document;stage.appendChild(frame)}else if(data.artifact_type==='graph'){stage.appendChild(graphView(data.graph))}else{stage.appendChild(formulaView(data.formula))}const timings=data.timings_ms||{};status.textContent='生成完成，耗时 '+((performance.now()-startedAt)/1000).toFixed(1)+' 秒'+(timings.model!=null?' · 模型 '+(timings.model/1000).toFixed(1)+' 秒':'')+(timings.render!=null?' · 渲染 '+timings.render.toFixed(0)+' ms':'')}catch(error){stage.innerHTML='<div class="error"></div>';stage.firstChild.textContent=error.message;status.textContent='生成失败，耗时 '+((performance.now()-startedAt)/1000).toFixed(1)+' 秒'}finally{button.disabled=false;button.textContent='生成可视化'}};
</script></body></html>"""
